import{_ as t,o as a,c as o,ae as i}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"Pixiu Bill Import Guide","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/guide/07-pixiu-bill-import-guide.md","filePath":"v1/en/guide/07-pixiu-bill-import-guide.md"}'),r={name:"v1/en/guide/07-pixiu-bill-import-guide.md"};function l(n,e,s,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="pixiu-bill-import-guide" tabindex="-1">Pixiu Bill Import Guide <a class="header-anchor" href="#pixiu-bill-import-guide" aria-label="Permalink to &quot;Pixiu Bill Import Guide&quot;">​</a></h1><h2 id="📋-overview" tabindex="-1">📋 Overview <a class="header-anchor" href="#📋-overview" aria-label="Permalink to &quot;📋 Overview&quot;">​</a></h2><p>This guide shows how to export bills from <strong>Pixiu</strong> and import them into <strong>Koala</strong>.</p><p>Koala currently supports <strong>Pixiu CSV exports</strong> (CSV only).</p><hr><h2 id="📱-part-1-export-in-pixiu" tabindex="-1">📱 Part 1: Export in Pixiu <a class="header-anchor" href="#📱-part-1-export-in-pixiu" aria-label="Permalink to &quot;📱 Part 1: Export in Pixiu&quot;">​</a></h2><p>The menu name may vary by Pixiu version, but the flow is the same: go to export, choose a date range, export as CSV, then save the file.</p><h3 id="step-1-find-the-export-entry" tabindex="-1">Step 1: Find the export entry <a class="header-anchor" href="#step-1-find-the-export-entry" aria-label="Permalink to &quot;Step 1: Find the export entry&quot;">​</a></h3><ol><li>Open Pixiu</li><li>Go to <strong>Me</strong></li><li>Find <strong>Data export / Export bills</strong> (wording may differ)</li></ol><h3 id="step-2-select-the-time-range" tabindex="-1">Step 2: Select the time range <a class="header-anchor" href="#step-2-select-the-time-range" aria-label="Permalink to &quot;Step 2: Select the time range&quot;">​</a></h3><ol><li>Choose the time range (e.g. last month / last 3 months)</li><li>Confirm and start export</li></ol><blockquote><p>💡 Tips:</p><ul><li>Export up to 3 months at a time to keep the file manageable.</li><li>For a large history, export multiple files and import them in batches.</li></ul></blockquote><h3 id="step-3-export-as-csv-and-save" tabindex="-1">Step 3: Export as CSV and save <a class="header-anchor" href="#step-3-export-as-csv-and-save" aria-label="Permalink to &quot;Step 3: Export as CSV and save&quot;">​</a></h3><ol><li>Choose export format: <strong>CSV</strong></li><li>Save the exported CSV file to your device (or share → Save to Files)</li><li>Remember the file location for import</li></ol><hr><h2 id="📱-part-2-import-into-koala" tabindex="-1">📱 Part 2: Import into Koala <a class="header-anchor" href="#📱-part-2-import-into-koala" aria-label="Permalink to &quot;📱 Part 2: Import into Koala&quot;">​</a></h2><h3 id="step-1-open-the-import-page" tabindex="-1">Step 1: Open the import page <a class="header-anchor" href="#step-1-open-the-import-page" aria-label="Permalink to &quot;Step 1: Open the import page&quot;">​</a></h3><ol><li>Open Koala</li><li>Tap <strong>Settings</strong></li><li>Find <strong>Bill Import</strong></li><li>Enter the bill import page</li></ol><h3 id="step-2-choose-the-import-source" tabindex="-1">Step 2: Choose the import source <a class="header-anchor" href="#step-2-choose-the-import-source" aria-label="Permalink to &quot;Step 2: Choose the import source&quot;">​</a></h3><ol><li>Tap <strong>Import source</strong></li><li>Select <strong>Pixiu</strong></li></ol><blockquote><p>⚠️ Important: You must choose <strong>Pixiu</strong>, otherwise validation may fail or fields may be parsed incorrectly.</p></blockquote><h3 id="step-3-pick-the-file" tabindex="-1">Step 3: Pick the file <a class="header-anchor" href="#step-3-pick-the-file" aria-label="Permalink to &quot;Step 3: Pick the file&quot;">​</a></h3><ol><li>Tap <strong>File path</strong></li><li>Select the CSV file exported from Pixiu</li><li>Confirm the file name is shown</li></ol><h3 id="step-4-link-a-ledger" tabindex="-1">Step 4: Link a ledger <a class="header-anchor" href="#step-4-link-a-ledger" aria-label="Permalink to &quot;Step 4: Link a ledger&quot;">​</a></h3><ol><li>Tap <strong>Linked ledger</strong></li><li>Choose the target ledger</li></ol><h3 id="step-5-parse-and-preview" tabindex="-1">Step 5: Parse and preview <a class="header-anchor" href="#step-5-parse-and-preview" aria-label="Permalink to &quot;Step 5: Parse and preview&quot;">​</a></h3><ol><li>Tap <strong>Parse</strong> (top-right)</li><li>After parsing succeeds, Koala opens the preview page</li><li>You can edit/delete single records, or batch-skip invalid records</li></ol><h3 id="step-6-import" tabindex="-1">Step 6: Import <a class="header-anchor" href="#step-6-import" aria-label="Permalink to &quot;Step 6: Import&quot;">​</a></h3><ol><li>Tap <strong>Import</strong> after confirming everything looks correct</li><li>Wait for import to finish</li></ol><hr><h2 id="📋-pixiu-csv-format-reference" tabindex="-1">📋 Pixiu CSV format (reference) <a class="header-anchor" href="#📋-pixiu-csv-format-reference" aria-label="Permalink to &quot;📋 Pixiu CSV format (reference)&quot;">​</a></h2><p>Koala validates Pixiu CSV as follows:</p><ul><li>The first row must be the header row</li><li>The header must contain <strong>10 columns</strong></li><li>Fields are separated by a comma <code>,</code> (standard CSV)</li></ul><h3 id="columns-in-order" tabindex="-1">Columns (in order) <a class="header-anchor" href="#columns-in-order" aria-label="Permalink to &quot;Columns (in order)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Column meaning</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td>Date</td><td>Supports <code>yyyy-MM-dd</code> / <code>yyyy/MM/dd</code>, and the year must be ≥ 2016; otherwise it’s treated as invalid</td></tr><tr><td>2</td><td>Parent category</td><td>Used to match Koala’s parent category name</td></tr><tr><td>3</td><td>Type</td><td>Must contain the keyword “支出” (expense) or “收入” (income); if it contains “收入”, Koala imports it as income, otherwise as expense</td></tr><tr><td>4</td><td>Child category</td><td>Used to match Koala’s child category name</td></tr><tr><td>5</td><td>Inflow amount</td><td>Income amount (a leading <code>-</code> is allowed; Koala removes the sign on import)</td></tr><tr><td>6</td><td>Outflow amount</td><td>Expense amount (a leading <code>-</code> is allowed; Koala removes the sign on import)</td></tr><tr><td>7</td><td>Currency code</td><td>For example <code>CNY</code> / <code>USD</code>; if empty, Koala uses the ledger’s default currency</td></tr><tr><td>8</td><td>Account</td><td>Account name (matched to Koala accounts; created during import if missing)</td></tr><tr><td>9</td><td>Tags</td><td>Multiple tags separated by commas (<code>,</code>), also supports Chinese comma <code>，</code></td></tr><tr><td>10</td><td>Note</td><td>Note text</td></tr></tbody></table><h3 id="mapping-into-koala" tabindex="-1">Mapping into Koala <a class="header-anchor" href="#mapping-into-koala" aria-label="Permalink to &quot;Mapping into Koala&quot;">​</a></h3><ul><li>Date → bill date</li><li>Type (expense/income keyword) → bill type</li><li>Parent + child category → category (if not matched, it will be marked as incomplete on the preview page)</li><li>Inflow/outflow → amount (Koala chooses the column based on bill type)</li><li>Account → account (matched by name; created if missing)</li><li>Tags → tags (matched/created and linked to the record)</li><li>Note → note</li><li>Currency code → bill currency (matched by code; falls back to the ledger currency if not matched)</li></ul><hr><h2 id="⚠️-notes" tabindex="-1">⚠️ Notes <a class="header-anchor" href="#⚠️-notes" aria-label="Permalink to &quot;⚠️ Notes&quot;">​</a></h2><ol><li><strong>No automatic deduplication</strong>: Importing the same file twice will create duplicate bills. Avoid importing the same time range repeatedly.</li><li><strong>Category matching</strong>: Koala matches by “parent + child” names. If matching fails, the preview page will show it as incomplete; select the correct category before importing.</li><li><strong>Account validity</strong>: If the account name is empty or only symbols, it may be treated as invalid and require you to fill it in.</li><li><strong>CSV encoding</strong>: UTF-8 and GBK are supported. If you see garbled text, re-export as UTF-8 or convert the encoding and import again.</li></ol><hr><h2 id="🔧-faq" tabindex="-1">🔧 FAQ <a class="header-anchor" href="#🔧-faq" aria-label="Permalink to &quot;🔧 FAQ&quot;">​</a></h2><h3 id="q1-header-length-is-incorrect" tabindex="-1">Q1: “Header length is incorrect”. <a class="header-anchor" href="#q1-header-length-is-incorrect" aria-label="Permalink to &quot;Q1: “Header length is incorrect”.&quot;">​</a></h3><p>Make sure the first header row has exactly <strong>10 columns</strong>. Common causes:</p><ol><li>The CSV file is not exported from Pixiu</li><li>Editing the file in Excel/WPS introduced extra separators so the column count changed</li><li>The file was saved in an incompatible CSV variant (e.g. semicolon-delimited)</li></ol><h3 id="q2-amount-is-wrong-or-becomes-0-after-import" tabindex="-1">Q2: Amount is wrong or becomes 0 after import. <a class="header-anchor" href="#q2-amount-is-wrong-or-becomes-0-after-import" aria-label="Permalink to &quot;Q2: Amount is wrong or becomes 0 after import.&quot;">​</a></h3><p>Check:</p><ol><li>The “Type” column contains the keyword for expense/income (this decides whether Koala reads inflow or outflow)</li><li>The corresponding amount column has a numeric value (<code>-</code> is allowed; Koala removes it)</li></ol><h3 id="q3-categories-don-t-match" tabindex="-1">Q3: Categories don’t match. <a class="header-anchor" href="#q3-categories-don-t-match" aria-label="Permalink to &quot;Q3: Categories don’t match.&quot;">​</a></h3><p>On the preview page, tap a record and select the correct category manually; or create categories in Koala with the same names as in the Pixiu export, then parse again.</p><hr><p><strong>Last updated</strong>: May 2026</p>',52)])])}const u=t(r,[["render",l]]);export{m as __pageData,u as default};
